using System;
using System.Collections.Generic;
using System.Drawing;
namespace Downfield {
public partial class Franchise {
 public float AwardValue(SeasonProduction p,string type){if(type!="MVP")return p.OffenseScore;Standing team=Table().Find(t=>t.Team==p.Team);return p.OffenseScore+(team==null?0:team.W*4);}
 public List<SeasonProduction> StatLeaders(int category){List<SeasonProduction> list=Production.FindAll(p=>(p.Role=="QB"||p.Role=="RB"||p.Role=="WR"||p.Role=="TE")&&(p.PassYards+p.RushYards+p.RecYards+p.PassTD+p.RushTD+p.RecTD>0));Dictionary<int,float> scores=new Dictionary<int,float>();List<Standing> table=Table();foreach(SeasonProduction p in list){Standing team=table.Find(s=>s.Team==p.Team);scores[p.PlayerId]=category==0?p.OffenseScore+(team==null?0:team.W*4):category==1?p.OffenseScore:category==2?p.PassYards:category==3?p.RushYards:p.RecYards;}list.Sort((a,b)=>{int order=scores[b.PlayerId].CompareTo(scores[a.PlayerId]);return order!=0?order:a.PlayerId.CompareTo(b.PlayerId);});if(category>=2)list.RemoveAll(p=>category==2?p.PassYards==0:category==3?p.RushYards==0:p.RecYards==0);return list;}
}
public partial class GameForm {
 int raceCategory;static readonly string[] RaceTitles={"MVP","OFFENSE","PASSING","RUSHING","RECEIVING"};
 void ChangeRace(int category){raceCategory=(category+5)%5;selection=0;audio.Play("menu");Invalidate();}
 bool RaceNavigation(){if(screen!="leaders")return false;if(input.Pressed(Input.LB)||input.Pressed(Input.Left)){ChangeRace(raceCategory-1);return true;}if(input.Pressed(Input.RB)||input.Pressed(Input.Right)){ChangeRace(raceCategory+1);return true;}return false;}
 List<string> RaceRows(){List<string> rows=new List<string>();foreach(SeasonProduction p in franchise.StatLeaders(raceCategory))rows.Add(p.Name+" / "+franchise.Teams[p.Team].Mascot);if(rows.Count==0)rows.Add("PLAY A GAME TO START THE RACE");rows.Add("BACK");return rows;}
 void DrawAwardRaces(){FrontHeader("STATS + AWARD RACES");for(int i=0;i<5;i++)DesignButton(RaceTitles[i],40+i*240,166,224,40,300+i,i==raceCategory);List<SeasonProduction> list=franchise.StatLeaders(raceCategory);int page=selection/6*6;TextAt("PLAYER / TEAM",50,228,10,Muted);TextAt("PASS YDS",354,228,10,Muted);TextAt("RUSH YDS",464,228,10,Muted);TextAt("REC YDS",574,228,10,Muted);TextAt("TD",686,228,10,Muted);TextAt(raceCategory<2?"RACE":"RANK",734,228,10,Muted);
  for(int i=page;i<Math.Min(page+6,list.Count);i++){SeasonProduction p=list[i];float y=258+(i-page)*65;bool selected=selection==i;Rect(40,y,750,58,selected?Color.FromArgb(62,91,94):Color.FromArgb(35,44,58));PlayerPortrait(franchise.Players.Find(a=>a.Id==p.PlayerId)??new ClubPlayer{Name=p.Name,Role=p.Role,Team=p.Team},48,y+4,49);TextAt((i+1)+" "+p.Name,98,y+8,11,selected?Gold:White);TextAt(Clip(franchise.Teams[p.Team].Mascot,16)+" / "+p.Role,98,y+34,10,Muted);TextAt(p.PassYards.ToString(),364,y+20,11,White);TextAt(p.RushYards.ToString(),474,y+20,11,White);TextAt(p.RecYards.ToString(),584,y+20,11,White);TextAt((p.PassTD+p.RushTD+p.RecTD).ToString(),690,y+20,11,Gold);TextAt(raceCategory<2?Math.Round(franchise.AwardValue(p,raceCategory==0?"MVP":"OPOTY")).ToString():(i+1).ToString(),738,y+20,10,Mint);HitArea(40,y,750,58,i);}
  if(list.Count==0)TextAt("PLAY A GAME TO START THE RACE",60,285,14,White);Panel(820,226,410,425);if(selection<list.Count){SeasonProduction p=list[selection];ClubPlayer player=franchise.Players.Find(a=>a.Id==p.PlayerId)??new ClubPlayer{Name=p.Name,Role=p.Role,Team=p.Team};PlayerPortrait(player,1070,241,96);TextAt(p.Name,842,253,18,Gold);TextAt(p.Role,842,292,14,White);TextAt(franchise.Teams[p.Team].Mascot,842,344,13,Mint);TextAt("PASSING "+p.PassYards+" YDS / "+p.PassTD+" TD",842,387,11,White);TextAt("RUSHING "+p.RushYards+" YDS / "+p.RushTD+" TD",842,425,11,White);TextAt("RECEIVING "+p.RecYards+" YDS / "+p.RecTD+" TD",842,463,11,White);TextAt(p.Catches+" CATCHES / "+p.Picks+" INTERCEPTIONS",842,501,11,Muted);Standing team=franchise.Table().Find(t=>t.Team==p.Team);TextAt("TEAM "+team.W+"W "+team.L+"L "+team.T+"T",842,541,12,Gold);if(raceCategory<2){float first=franchise.AwardValue(list[0],raceCategory==0?"MVP":"OPOTY"),current=franchise.AwardValue(p,raceCategory==0?"MVP":"OPOTY");Meter(842,584,358,(int)(100*current/Math.Max(1,first)),Mint);TextAt(selection==0?"CURRENT FRONTRUNNER":"IN THE HUNT / RANK "+(selection+1),842,614,11,Mint);}}
  DesignButton("BACK",40,674,235,44,Math.Max(1,list.Count),selection>=list.Count);TextAt(Hint("LB/RB CATEGORY / UP-DOWN PLAYER","LEFT-RIGHT CATEGORY / UP-DOWN PLAYER"),300,687,10,Muted);TextAt(raceCategory==0?"MOST VALUABLE PLAYER: PRODUCTION + TEAM WINS":raceCategory==1?"OFFENSIVE PLAYER OF THE YEAR: PRODUCTION":"LEAGUE LEADERS / ALL 12 TEAMS",40,735,11,Mint);}
}
}
